import '../financial/tax_shield_provider.dart';
import '../financial/mileage_engine.dart';
import '../../features/boxes/data/models/box_model.dart';
import '../../features/invoices/data/models/invoice_model.dart';
import '../../features/receipt_scanning/domain/entities/receipt.dart';

/// Intent classification for financial natural language queries.
enum CopilotQueryIntent {
  spendByCategory,
  spendByBox,
  totalRevenue,
  totalExpenses,
  taxReserveAndSafeToSpend,
  overdueInvoices,
  mileageSummary,
  topMerchants,
  generalOverview,
}

/// Structured response generated by the offline natural language financial copilot.
class CopilotAnswer {
  final CopilotQueryIntent intent;
  final String query;
  final String headline;
  final String detailedExplanation;
  final double? primaryFigure;
  final String? figureFormatted;
  final Map<String, dynamic> metadata;
  final List<String> suggestions;

  const CopilotAnswer({
    required this.intent,
    required this.query,
    required this.headline,
    required this.detailedExplanation,
    this.primaryFigure,
    this.figureFormatted,
    this.metadata = const {},
    this.suggestions = const [],
  });
}

/// Zero-cloud on-device Natural Language Financial Copilot engine.
class FinancialCopilotService {
  /// Interprets a natural language [query] and evaluates the answer over the local financial database.
  static CopilotAnswer answerQuery({
    required String query,
    required List<Receipt> receipts,
    required List<InvoiceModel> invoices,
    required List<BoxModel> boxes,
    required List<MileageTrip> mileageTrips,
    required TaxShieldCalculation taxCalculation,
  }) {
    final q = query.toLowerCase().trim();

    // 1. Tax Reserve / Safe to spend queries
    if (q.contains('tax') ||
        q.contains('safe to spend') ||
        q.contains('safely spend') ||
        q.contains('reserve') ||
        q.contains('stash')) {
      final safeToSpend = taxCalculation.safeToSpend;
      final locked = taxCalculation.lockedTaxShield;
      final rate = (taxCalculation.effectiveTaxRate * 100).toStringAsFixed(0);

      return CopilotAnswer(
        intent: CopilotQueryIntent.taxReserveAndSafeToSpend,
        query: query,
        headline: 'Safe-to-Spend: \$${safeToSpend.toStringAsFixed(2)}',
        detailedExplanation:
            'Your locked quarterly tax reserve is \$${locked.toStringAsFixed(2)} ($rate% withholding rate). '
            'You have earned \$${taxCalculation.taxSavingsEarned.toStringAsFixed(2)} in tax deduction shields from business expenses.',
        primaryFigure: safeToSpend,
        figureFormatted: '\$${safeToSpend.toStringAsFixed(2)}',
        suggestions: ['Simulate an expense', 'View tax profile', 'Export CPA portal'],
      );
    }

    // 2. Overdue or unpaid invoices
    if (q.contains('overdue') || q.contains('unpaid') || q.contains('owe') || q.contains('receivable')) {
      final unpaid = invoices.where((i) => i.status == InvoiceStatus.sent || i.status == InvoiceStatus.draft).toList();
      final totalUnpaid = unpaid.fold(0.0, (sum, i) => sum + i.amount);

      return CopilotAnswer(
        intent: CopilotQueryIntent.overdueInvoices,
        query: query,
        headline: 'Uncollected Invoices: \$${totalUnpaid.toStringAsFixed(2)}',
        detailedExplanation: 'You have ${unpaid.length} outstanding invoice(s) totaling \$${totalUnpaid.toStringAsFixed(2)}.',
        primaryFigure: totalUnpaid,
        figureFormatted: '\$${totalUnpaid.toStringAsFixed(2)}',
        suggestions: ['Send dunning reminder', 'View all invoices', 'Create new invoice'],
      );
    }

    // 3. Mileage queries
    if (q.contains('mileage') || q.contains('travel') || q.contains('drive') || q.contains('trips')) {
      final summary = MileageEngine.calculateSummary(mileageTrips);

      return CopilotAnswer(
        intent: CopilotQueryIntent.mileageSummary,
        query: query,
        headline: 'Mileage Deductions: \$${summary.totalDeductibleAmount.toStringAsFixed(2)}',
        detailedExplanation:
            'You have logged ${summary.tripCount} trip(s) covering ${summary.totalDistanceMiles.toStringAsFixed(1)} miles '
            '(${summary.totalDistanceKm.toStringAsFixed(1)} km) yielding \$${summary.totalDeductibleAmount.toStringAsFixed(2)} in tax deductions.',
        primaryFigure: summary.totalDeductibleAmount,
        figureFormatted: '\$${summary.totalDeductibleAmount.toStringAsFixed(2)}',
        suggestions: ['Log new trip', 'Change mileage preset rate'],
      );
    }

    // 4. Box / Project specific queries
    for (final box in boxes) {
      if (q.contains(box.name.toLowerCase())) {
        final boxReceipts = receipts.where((r) => r.boxId == box.id).toList();
        final boxTotal = boxReceipts.fold(0.0, (sum, r) => sum + r.totalAmount);

        return CopilotAnswer(
          intent: CopilotQueryIntent.spendByBox,
          query: query,
          headline: '${box.name} Expenses: \$${boxTotal.toStringAsFixed(2)}',
          detailedExplanation: 'A total of ${boxReceipts.length} receipt(s) are allocated to Box "${box.name}".',
          primaryFigure: boxTotal,
          figureFormatted: '\$${boxTotal.toStringAsFixed(2)}',
          suggestions: ['View Box details', 'Generate Box P&L statement'],
        );
      }
    }

    // 5. Top Merchants query
    if (q.contains('merchant') || q.contains('vendor') || q.contains('where did i spend')) {
      final Map<String, double> merchantTotals = {};
      for (final r in receipts) {
        final name = r.merchantName.trim();
        if (name.isNotEmpty) {
          merchantTotals[name] = (merchantTotals[name] ?? 0.0) + r.totalAmount;
        }
      }

      final sorted = merchantTotals.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
      final top3 = sorted.take(3).map((e) => '${e.key} (\$${e.value.toStringAsFixed(2)})').join(', ');

      return CopilotAnswer(
        intent: CopilotQueryIntent.topMerchants,
        query: query,
        headline: 'Top Merchants: ${sorted.isNotEmpty ? sorted.first.key : 'None'}',
        detailedExplanation: 'Your highest expenditure vendors are: $top3.',
        suggestions: ['View price drift watch', 'Filter receipts by merchant'],
      );
    }

    // Default: General Overview
    final totalSpent = receipts.fold(0.0, (sum, r) => sum + r.totalAmount);
    final totalInvoiced = invoices.where((i) => i.status == InvoiceStatus.settled).fold(0.0, (sum, i) => sum + i.amount);

    return CopilotAnswer(
      intent: CopilotQueryIntent.generalOverview,
      query: query,
      headline: 'Total Revenue: \$${totalInvoiced.toStringAsFixed(2)} | Spent: \$${totalSpent.toStringAsFixed(2)}',
      detailedExplanation:
          'Across ${receipts.length} scanned receipts and ${invoices.length} invoices, '
          'your net cash flow is \$${(totalInvoiced - totalSpent).toStringAsFixed(2)}.',
      primaryFigure: totalInvoiced - totalSpent,
      figureFormatted: '\$${(totalInvoiced - totalSpent).toStringAsFixed(2)}',
      suggestions: ['How much can I safely spend?', 'What are my top expenses?', 'Check overdue invoices'],
    );
  }
}
